import SwiftUI

/// A local-only tvOS entry point while the provider's account contract is unverified.
/// No credentials, media requests, or playback URLs are generated by this page.
struct MovieBoxBetaView: View {
    private enum Page: String, CaseIterable, Identifiable {
        case overview = "Overview"
        case movies = "Movies"
        case series = "TV Shows"
        case search = "Search"
        case account = "Account"

        var id: String { rawValue }

        var symbol: String {
            switch self {
            case .overview: "house"
            case .movies: "film"
            case .series: "tv"
            case .search: "magnifyingglass"
            case .account: "person.crop.circle"
            }
        }

        var detail: String {
            switch self {
            case .overview: "MovieBox Pro is not connected to DreamCAST yet."
            case .movies: "Movie listings will appear after a supported account connection is ready."
            case .series: "TV shows and episodes will appear after a supported account connection is ready."
            case .search: "Search will be available after we verify the provider's request format."
            case .account: "Choose how you want to connect your MovieBox Pro account."
            }
        }
    }

    private enum SignInMethod: String, CaseIterable, Identifiable {
        case code = "Code Login"
        case google = "Google"
        case email = "Email (unverified)"

        var id: String { rawValue }

        var symbol: String {
            switch self {
            case .code: "number.square"
            case .google: "person.crop.circle"
            case .email: "envelope"
            }
        }

        var explanation: String {
            switch self {
            case .code:
                "Enter the temporary TV code through MovieBox Pro on your iPhone."
            case .google:
                "Google sign-in needs a verified account redirect. No login window is opened yet."
            case .email:
                "The supplied iPhone app only shows Code Login and Google. Email access is not verified."
            }
        }
    }

    @State private var page: Page = .overview
    @State private var signInMethod: SignInMethod = .code

    var body: some View {
        ZStack {
            Color(red: 0.045, green: 0.06, blue: 0.09)
                .ignoresSafeArea()

            ScrollView {
                VStack(alignment: .leading, spacing: 34) {
                    HStack(spacing: 24) {
                        Image(systemName: "play.tv.fill")
                            .font(.system(size: 68))
                            .foregroundStyle(.cyan)

                        VStack(alignment: .leading, spacing: 10) {
                            Text("MovieBox Pro")
                                .font(.largeTitle.bold())
                            Text("DreamCAST beta")
                                .font(.title3)
                                .foregroundStyle(.secondary)
                        }
                    }

                    HStack(spacing: 20) {
                        ForEach(Page.allCases) { item in
                            Button {
                                page = item
                            } label: {
                                Label(item.rawValue, systemImage: item.symbol)
                                    .font(.headline)
                                    .frame(minWidth: 150, minHeight: 55)
                            }
                            .buttonStyle(.bordered)
                            .tint(page == item ? .cyan : .gray)
                        }
                    }

                    VStack(alignment: .leading, spacing: 16) {
                        Text(page.rawValue)
                            .font(.title.bold())
                        Text(page.detail)
                            .font(.title3)
                            .foregroundStyle(.secondary)

                        HStack(spacing: 14) {
                            Image(systemName: "person.crop.circle.badge.exclamationmark")
                                .foregroundStyle(.yellow)
                            Text("Account status: Not connected")
                                .font(.headline)
                        }
                        .padding(.top, 10)
                    }
                    .frame(maxWidth: .infinity, minHeight: 190, alignment: .leading)
                    .padding(32)
                    .background(.white.opacity(0.07), in: RoundedRectangle(cornerRadius: 22))

                    if page == .account {
                        VStack(alignment: .leading, spacing: 22) {
                            Text("Sign-in options")
                                .font(.title2.bold())

                            HStack(spacing: 22) {
                                ForEach(SignInMethod.allCases) { method in
                                    Button {
                                        signInMethod = method
                                    } label: {
                                        Label(method.rawValue, systemImage: method.symbol)
                                            .font(.headline)
                                            .frame(minWidth: 190, minHeight: 55)
                                    }
                                    .buttonStyle(.bordered)
                                    .tint(signInMethod == method ? .cyan : .gray)
                                }
                            }

                            Text(signInMethod.explanation)
                                .font(.title3)
                                .foregroundStyle(.secondary)

                            if signInMethod == .code {
                                VStack(alignment: .leading, spacing: 14) {
                                    Text("Your Apple TV code")
                                        .font(.headline)

                                    HStack(spacing: 16) {
                                        Image(systemName: "lock.shield")
                                            .foregroundStyle(.cyan)
                                        Text("Not issued")
                                            .font(.title2.bold())
                                    }

                                    Text("1. Open MovieBox Pro on your iPhone.")
                                    Text("2. Open its settings and choose Code Login.")
                                    Text("3. Enter the code shown on your Apple TV and confirm.")

                                    Text("Code requests are disabled until the provider's login API is verified.")
                                        .font(.footnote)
                                        .foregroundStyle(.secondary)
                                        .padding(.top, 8)
                                }
                                .font(.body)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .padding(26)
                                .background(.black.opacity(0.2), in: RoundedRectangle(cornerRadius: 16))
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(32)
                        .background(.white.opacity(0.07), in: RoundedRectangle(cornerRadius: 22))
                    }

                    Text("This beta screen is local only. No MovieBox sign-in or streaming is active.")
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: 1460, alignment: .leading)
                .padding(.horizontal, 90)
                .padding(.vertical, 64)
            }
        }
    }
}
